{
  "statements": [
    {
      "id": "3.1.5a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"not safe to pass\")",
      "text": "a driver MUST NOT pass a vehicle WHEN a solid line is at the left of the driver's lane",
      "sources": [
        {
          "id": "m20",
          "quote": "Pavement markings divide traffic lanes, show turning lanes, mark pedestrian crossings, indicate obstacles and tell you when it is not safe to pass."
        },
        {
          "id": "m21",
          "quote": "A solid line at the left of your lane means it is unsafe to pass. ('A' should not pass.)"
        },
        {
          "id": "m22",
          "quote": "vehicles travelling beside a solid yellow line"
        }
      ],
      "flags": [
        {
          "code": "M",
          "span": "unsafe to pass",
          "note": "The handbook uses 'unsafe' rather than explicit legal wording like 'illegal' or 'prohibited', but the context of pavement markings indicating safety suggests a legal restriction."
        }
      ],
      "links": [],
      "note": "The figure m22 illustrates the solid line condition."
    },
    {
      "id": "3.1.6a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"may pass\")",
      "text": "a driver MAY pass a vehicle WHEN a broken line is at the left of the driver's lane AND the way is clear AND there are enough broken lines ahead to complete the pass safely",
      "sources": [
        {
          "id": "m23",
          "quote": "A broken line at the left of your lane means you may pass if the way is clear. ('A' may pass if there are enough broken lines ahead to complete the pass safely.)"
        },
        {
          "id": "m24",
          "quote": "vehicles travelling beside broken yellow lines"
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "enough broken lines ahead to complete the pass safely",
          "note": "Subjective judgment of distance and safety; no fixed metric for 'enough' lines."
        }
      ],
      "links": [],
      "note": "The figure m24 illustrates the broken line condition."
    }
  ]
}
